int vfs_rename(struct inode *old_dir, struct dentry *old_dentry,
               struct inode *new_dir, struct dentry *new_dentry,
               struct inode **delegated_inode, unsigned int flags) {
    int error;

    if (old_dentry->d_inode == new_dentry->d_inode &&
        old_dir == new_dir && !dentry_needs_revalidate(old_dentry))
        return 0;

    error = -EACCES;
    if (!inode_is_locked(old_dir) || !inode_is_locked(new_dir))
        return error;

    error = inode_permission(old_dir, MAY_WRITE | MAY_REMOVE);
    if (error)
        return error;

    error = inode_permission(new_dir, MAY_WRITE | MAY_CREATE);
    if (error)
        return error;

    if (S_ISDIR(old_dentry->d_inode->i_mode)) {
        if (flags & RENAME_EXCHANGE) {
            error = vfs_rename_exchange(old_dir, old_dentry, new_dir, new_dentry);
        } else {
            error = vfs_rename_dir(old_dir, old_dentry, new_dir, new_dentry);
        }
    } else {
        error = old_dir->i_op->rename(old_dir, old_dentry, new_dir, new_dentry);
    }

    if (!error) {
        d_move(old_dentry, new_dentry);
        fsnotify_move(old_dir, new_dir, old_dentry, new_dentry);
    }

    return error;
}

int vfs_rename(struct inode *old_dir, struct dentry *old_dentry,
               struct inode *new_dir, struct dentry *new_dentry,
               struct inode **delegated_inode, unsigned int flags)
{
    int error;
    struct inode *old_inode = old_dentry->d_inode;
    struct inode *new_inode = new_dentry->d_inode;
    struct super_block *old_sb = old_dir->i_sb;
    struct super_block *new_sb = new_dir->i_sb;

    if (old_sb != new_sb)
        return -EXDEV;

    if (old_inode == new_inode && !flags)
        return 0;

    error = -EINVAL;
    if (S_ISDIR(old_inode->i_mode) && !(flags & RENAME_DIR))
        goto out;

    error = -EISDIR;
    if (!S_ISDIR(old_inode->i_mode) && (flags & RENAME_DIR))
        goto out;

    error = security_dentry_rename(old_dir, old_dentry, new_dir, new_dentry, flags);
    if (error)
        goto out;

    if (flags & RENAME_NOREPLACE) {
        if (new_inode)
            goto out;
    }

    error = -EPERM;
    if (IS_IMMUTABLE(old_inode) || IS_APPEND(old_inode) ||
        (S_ISDIR(old_inode->i_mode) && IS_APPEND(new_dir)))
        goto out;

    if (new_inode && (S_ISDIR(new_inode->i_mode) && IS_APPEND(new_inode)))
        goto out;

    error = -EMLINK;
    if (S_ISDIR(old_inode->i_mode) && old_dir->i_nlink >=
        old_dir->i_sb->s_max_links)
        goto out;

    if (new_inode && S_ISDIR(new_inode->i_mode) &&
        new_dir->i_nlink >= new_dir->i_sb->s_max_links)
        goto out;

    error = -ENOTEMPTY;
    if (S_ISDIR(old_inode->i_mode) && (flags & RENAME_EXCHANGE) &&
        new_inode && new_inode->i_nlink > 1)
        goto out;

    if (new_inode) {
        error = -EROFS;
        if (IS_RDONLY(new_inode))
            goto out;

        error = -EPERM;
        if (IS_APPEND(new_inode) || IS_IMMUTABLE(new_inode))
            goto out;
    }

    if (old_dir->i_op && old_dir->i_op->rename) {
        error = old_dir->i_op->rename(old_dir, old_dentry, new_dir,
                                      new_dentry, flags);
    } else {
        error = -ENOSYS;
    }

    if (!error) {
        if (!new_inode)
            d_instantiate(new_dentry, old_inode);
        d_move(old_dentry, new_dentry);
        if (S_ISDIR(old_inode->i_mode)) {
            if (flags & RENAME_EXCHANGE) {
                if (new_inode)
                    old_inode->i_nlink--;
                new_inode->i_nlink++;
            }
        }
        if (old_inode != new_inode)
            old_inode->i_ctime = CURRENT_TIME;
        if (new_inode)
            new_inode->i_ctime = CURRENT_TIME;
        fsnotify_move(old_dir, new_dir, old_dentry, new_dentry);
    }

out:
    return error;
}

int vrename(struct inode *old_dir, struct dentry *old_dentry, struct inode *new_dir, struct dentry *new_dentry, struct inode **delegated_inode, unsigned int flags) {
    int err;

    if (dentry_same_name(old_dentry, new_dentry) && same_inode(old_dir, new_dir)) {
        return 0;
    }

    err = inode_permission(old_dir, MAY_WRITE | MAY_EXEC);
    if (err)
        return err;

    err = inode_permission(new_dir, MAY_WRITE | MAY_EXEC);
    if (err)
        return err;

    if (flags & RENAME_EXCHANGE) {
        struct dentry *tmp_dentry;

        tmp_dentry = dget(new_dentry);

        err = old_dir->i_op->rename(old_dir, old_dentry, new_dir, new_dentry);
        if (err)
            goto out;

        err = new_dir->i_op->rename(new_dir, tmp_dentry, old_dir, old_dentry);
        dput(tmp_dentry);
        if (err)
            goto out;
    } else {
        err = old_dir->i_op->rename(old_dir, old_dentry, new_dir, new_dentry);
        if (err)
            goto out;
    }

    d_move(old_dentry, new_dentry);
    fsnotify_move(old_dir, new_dir, old_dentry, new_dentry);

    return 0;

out:
    return err;
}

int vfs_rename(struct inode *old_dir, struct dentry *old_dentry,
               struct inode *new_dir, struct dentry *new_dentry,
               struct inode **delegated_inode, unsigned int flags)
{
    int error;

    if (old_dentry == new_dentry)
        return 0;

    error = security_path_rename(&old_dentry->d_parent->d_path,
                                 old_dentry, &new_dentry->d_parent->d_path,
                                 new_dentry, flags);
    if (error)
        return error;

    if (flags & RENAME_EXCHANGE) {
        error = old_dir->i_op->rename(old_dir, old_dentry, new_dir,
                                      new_dentry, flags);
        if (!error)
            fsnotify_oldname_init(old_dentry->d_name.name);
    } else {
        error = mnt_want_write_file(NULL);
        if (error)
            return error;

        error = old_dir->i_op->rename(old_dir, old_dentry, new_dir,
                                      new_dentry, flags);
        if (!error) {
            fsnotify_rename(old_dir, old_dentry, new_dir, new_dentry);
            d_move(old_dentry, new_dentry);
        }

        mnt_drop_write_file(NULL);
    }

    return error;
}

int vfat_rename(struct inode *old_dir, struct dentry *old_dentry,
                struct inode *new_dir, struct dentry *new_dentry,
                struct inode **delegated_inode, unsigned int flags)
{
    int error;

    /* Check if source and target are the same */
    if (old_dir == new_dir && old_dentry == new_dentry)
        return 0;

    /* Check for permissions to delete from old_dir and create in new_dir */
    error = -EACCES;
    if (!inode_permission(old_dir, MAY_WRITE | MAY_REMOVE))
        if (!inode_permission(new_dir, MAY_WRITE | MAY_CREATE))
            error = 0;

    if (error)
        return error;

    /* Handle special cases for directories */
    if (S_ISDIR(old_dentry->d_inode->i_mode)) {
        struct inode *old_inode = old_dentry->d_inode;
        struct inode *new_inode = new_dentry->d_inode;

        /* Check link count limits */
        if (old_inode->i_nlink >= MAX_LINKS)
            return -EMLINK;

        if (new_inode && new_inode->i_nlink >= MAX_LINKS)
            return -EMLINK;
    }

    /* Perform the rename through appropriate inode operations */
    error = old_dentry->d_inode->i_op->rename(old_dir, old_dentry,
                                             new_dir, new_dentry,
                                             delegated_inode, flags);
    if (error)
        return error;

    /* Notify filesystem of the move */
    fsnotify_move(old_dir, new_dir, old_dentry, new_dentry);

    /* Clean up resources if needed */
    d_move(old_dentry, new_dentry);

    return 0;
}
